const SYS = "You are a professional English to Spanish (Spain) localizer for BrainIQTest, an online IQ test and cognitive-training product.\nRules:\n- Address the user informally, using tu. Never usted.\n- Clear, direct, natural and simple. Never translate literally; rewrite so it reads like Spanish written by a native.\n- Active voice. Avoid noun-heavy phrasing.\n- Button labels and calls to action: use the infinitive (Empezar, Guardar, Descargar).\n- Follow RAE and Fundeu conventions for grammar, punctuation and capitalisation. Spanish uses sentence case, not Title Case.\n- Never translate brand names: BrainIQTest, BrainIQ. Never translate URLs or email addresses.\n- Placeholders and HTML tags must appear in the output exactly as in the source, unchanged and in the same order. Do not add or remove any.\n- Keep terminology consistent across all items in the batch.\n- Respect the context line: it says which screen the string appears on and whether it is a button, heading, label, placeholder or error message.\nReturn ONLY a JSON object of the form {\"t\":{\"<id>\":\"<spanish>\"}} with one entry per input id. No prose, no markdown.";

let statusAi = null, statusFb = null;
const st = $('List Statuses').first().json;
const arr = (st && st.body && st.body.custom_translation_statuses) || [];
for (const s of arr) {
  if (String(s.title) === 'AI_TO_REVIEW') statusAi = s.status_id;
  if (String(s.title) === 'EN_FALLBACK') statusFb = s.status_id;
}

const gl = [];
try {
  const g = $('Fetch Glossary').first().json;
  const body = (g && g.body) || {};
  const terms = (body.data && body.data.terms) || body.terms || [];
  for (const t of terms) {
    let es = '';
    for (const tr of (t.translations || [])) {
      const iso = tr.langId || tr.lang_iso || tr.language_iso || '';
      if (String(iso).toLowerCase().indexOf('es') === 0) es = tr.translation;
    }
    if (t.term && es) gl.push([String(t.term), String(es)]);
  }
} catch (e) { }

function clean(s) { return String(s === null || s === undefined ? '' : s); }

const targets = [];
for (const p of $('Fetch Keys').all()) {
  const b = (p.json && p.json.body) || {};
  if (!Array.isArray(b.keys)) continue;
  for (const k of b.keys) {
    if (k.is_plural) continue;
    let en = '', es = '', esStatuses = [];
    for (const tr of (k.translations || [])) {
      if (tr.language_iso === 'en') en = clean(tr.translation);
      if (tr.language_iso === 'es') { es = clean(tr.translation); esStatuses = tr.custom_translation_statuses || []; }
    }
    if (!en.trim()) continue;
    let isTm = false;
    for (const s of esStatuses) { if (String(s.title) === '100TM') isTm = true; }
    if (isTm) continue;
    const kn = k.key_name;
    const name = (typeof kn === 'string') ? kn : ((kn && (kn.web || kn.other)) || '');
    targets.push({ id: k.key_id, key: name, src: en, ctx: clean(k.description).slice(0, 180), had: es.trim() ? 1 : 0 });
  }
}

const SIZE = 20;
const out = [];
for (let i = 0; i < targets.length; i += SIZE) {
  const slice = targets.slice(i, i + SIZE);
  const payload = [];
  let joined = '';
  for (const t of slice) { payload.push({ id: String(t.id), key: t.key, context: t.ctx, source: t.src }); joined += ' ' + t.src; }
  const low = joined.toLowerCase();
  const terms = [];
  for (const g of gl) { if (low.indexOf(String(g[0]).toLowerCase()) >= 0 && terms.length < 25) terms.push(g[0] + ' = ' + g[1]); }
  let user = 'Translate these UI strings into Spanish.';
  if (terms.length) { user += '\n\nGlossary (use these exact terms):\n' + terms.join('\n'); }
  user += '\n\nItems:\n' + JSON.stringify(payload);
  out.push({ json: {
    batch: (i / SIZE) + 1,
    items: slice,
    status_ai: statusAi,
    status_fb: statusFb,
    total_targets: targets.length,
    glossary_terms: gl.length,
    body: {
      model: 'gpt-4o',
      temperature: 0.2,
      max_tokens: 4000,
      response_format: { type: 'json_object' },
      messages: [ { role: 'system', content: SYS }, { role: 'user', content: user } ]
    }
  }});
}
return out;

const all = $input.all();
const rows = [];
let fb = 0, over = 0;
let sAi = null, sFb = null, totalTargets = 0;
for (const r of all) {
  const j = r.json || {};
  if (!j.key_id) continue;
  sAi = j.status_ai; sFb = j.status_fb; totalTargets = j.total_targets;
  if (j.fallback) fb++;
  if (j.overwrote) over++;
  const sid = j.fallback ? sFb : sAi;
  rows.push({ key_id: j.key_id, translations: [{ language_iso: 'es', translation: j.es, is_reviewed: false, is_fuzzy: false, custom_translation_status_ids: sid ? [sid] : [] }] });
}
const CHUNK = 150;
const out = [];
for (let i = 0; i < rows.length; i += CHUNK) {
  out.push({ json: { chunk: (i / CHUNK) + 1, produced: rows.length, fallbacks: fb, overwritten: over, total_targets: totalTargets, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/keys', body: { keys: rows.slice(i, i + CHUNK) } } });
}
if (!out.length) { out.push({ json: { chunk: 0, produced: 0, fallbacks: 0, overwritten: 0, total_targets: totalTargets, url: 'https://api.lokalise.com/api2/projects/185916266aa3d6649ca6f7.57851232/keys', body: { keys: [] } } }); }
return out;

const plan = $('Build Write').first().json;
const res = $input.all();
let ok = 0, updated = 0;
const errors = [];
for (const r of res) {
  const j = r.json || {};
  const b = j.body || {};
  if (j.statusCode === 200 && Array.isArray(b.keys)) { ok++; updated += b.keys.length; }
  else errors.push({ statusCode: j.statusCode, err: JSON.stringify(b).slice(0, 300) });
}
return [{ json: { targets: plan.total_targets, produced: plan.produced, fallbacks: plan.fallbacks, overwritten_suspect_mt: plan.overwritten, requests: res.length, ok_requests: ok, keys_written: updated, errors: errors } }];

const job = $('Loop Batches').first().json;
const PH = /(\{\{[^}]*\}\}|\{[^}]*\}|%\d*\$?[sd@]|\[[A-Z_]+\])/g;
const TAG = /<\/?[a-zA-Z][^>]*>/g;
function inv(s, re) { const m = String(s || '').match(re) || []; const o = []; for (const x of m) o.push(x); o.sort(); return o.join('\u0001'); }

let map = {};
try {
  const r = $input.first().json;
  const body = (r && r.body) || {};
  const ch = body.choices || [];
  const txt = ch.length ? String(ch[0].message.content) : '';
  const cleanTxt = txt.replace(/```json/g, '').replace(/```/g, '').trim();
  const parsed = JSON.parse(cleanTxt);
  map = parsed.t || parsed;
} catch (e) { map = {}; }

const rows = [];
for (const it of (job.items || [])) {
  const got = map[String(it.id)];
  let text = (got === null || got === undefined) ? '' : String(got);
  let fallback = false;
  if (!text.trim()) { fallback = true; }
  else if (inv(it.src, PH) !== inv(text, PH)) { fallback = true; }
  else if (inv(it.src, TAG) !== inv(text, TAG)) { fallback = true; }
  if (fallback) { text = it.src; }
  rows.push({ json: { key_id: it.id, key: it.key, source: it.src, es: text, fallback: fallback ? 1 : 0, overwrote: it.had, status_ai: job.status_ai, status_fb: job.status_fb, batch: job.batch, total_targets: job.total_targets } });
}
return rows;
